parameters.jsonBody:
={
  "contents": [
    {
      "parts": [
        {
          "text": "Generate 5 high-frequency academic IELTS/TOEIC vocabulary words for today in clean JSON format adhering strictly to this schema: { \"topic\": \"IELTS Academic & Daily Wisdom\", \"deckTitle\": \"Từ vựng hôm nay (Daily Vocab)\", \"cards\": [ { \"front\": \"word\", \"phonetic\": \"/IPA/\", \"back\": \"Nghĩa tiếng Việt ngắn gọn\", \"exampleEn\": \"English sentence\", \"exampleVi\": \"Dịch tiếng Việt\" } ] }. Output ONLY pure JSON."
        }
      ]
    }
  ],
  "generationConfig": {
    "responseMimeType": "application/json",
    "temperature": 0.2
  }
}

parameters.jsCode:
// Extract generated JSON content from Gemini API response
const responseText = $input.first().json.candidates[0].content.parts[0].text;
let parsedData;
try {
  parsedData = JSON.parse(responseText.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim());
} catch (e) {
  parsedData = {
    topic: "IELTS Focus",
    deckTitle: "Từ vựng thông minh hôm nay",
    cards: [
      {
        front: "breakthrough",
        phonetic: "/ˈbreɪk.θruː/",
        back: "Bước đột phá, phát minh quan trọng",
        exampleEn: "This discovery is a major breakthrough in science.",
        exampleVi: "Phát hiện này là một bước đột phá lớn trong khoa học."
      },
      {
        front: "resilient",
        phonetic: "/rɪˈzɪl.jənt/",
        back: "Kiên cường, bền bỉ phục hồi",
        exampleEn: "Students are exceptionally resilient in overcoming challenges.",
        exampleVi: "Học sinh đặc biệt kiên cường trong việc vượt qua thử thách."
      }
    ]
  };
}

return [{
  json: {
    topic: parsedData.topic || "IELTS Daily",
    deckTitle: parsedData.deckTitle || `Từ vựng hôm nay - ${new Date().toLocaleDateString('vi-VN')}`,
    category: "Intermediate",
    color: "from-indigo-600 to-violet-600",
    cards: parsedData.cards || [],
    broadcastNotification: true,
    notificationMessage: `✨ Bộ từ vựng hôm nay "${parsedData.deckTitle || 'Daily Vocab'}" đã sẵn sàng! Dành 3 phút ôn luyện để giữ vững chuỗi Streak nhé!`
  }
}];
